DEFAULT_ENGINE = "stable"
OUT_RATE = 22050
# Level: the content RMS (the frames that carry the sound) is brought to TARGET_RMS_DB, and a look-ahead limiter holds
# the peaks at CEILING_DB; a clip whose transients would have to be squashed by more than MAX_LIMIT_DB stops short of the
# target instead. Peak normalising alone had left the real sounds 9 dB (median; up to 20) under the dense synthetic
# placeholders the rows' volume_db were tuned for.
TARGET_RMS_DB = -14.0
CEILING_DB = -2.0
MAX_LIMIT_DB = 6.0
