AUDIOGEN_INPUT_IDS = {"mode": 301, "prompt": 165, "duration": 221, "seed": 227, "channels": 256, "rate": 257,
                      "top_k": 264, "top_p": 265, "temperature": 266, "cfg": 267, "segments": 161}

# Per kind: the spectral-centroid ceiling (Hz, on the processed 22.05 kHz clip: a candidate above it is penalised while
# another passes; the lowest centroid wins among the rest), the high-pass corner (Hz), and `sub_max`: the largest share
# of energy under SUB_HZ a candidate may carry without a penalty. Garry wants a lower register, but a phone speaker
# reproduces nothing under about 150 Hz: a clip that is mostly sub-bass (the first wind loops were 99 % under 60 Hz, a
# drone) is silent in the game, so the score steers towards low-MID sounds. A row's `pitch` (semitones, negative =
# lower) is applied by varispeed for every kind (`pitch_shift`): the clip gets longer and lower with every transient
# intact, and a one-shot is cut to its `seconds` afterwards anyway. (The plan had librosa's phase vocoder for the tonal
# kinds, length kept; librosa 0.10.0 on this PC's numpy 1.22 has no `_phasor_angles` loop for any dtype, so it never
# ran, and a method that depends on the machine would make the picks irreproducible.)
KINDS = {
    "boom": {"ceiling": 1600, "hp": 40, "sub_max": 0.8},
    "impact": {"ceiling": 2600, "hp": 50, "sub_max": 0.6},
    "shot": {"ceiling": 3000, "hp": 50, "sub_max": 0.6},
    "whoosh": {"ceiling": 2800, "hp": 60, "sub_max": 0.6},
    "creature": {"ceiling": 2400, "hp": 60, "sub_max": 0.6},
    "sting": {"ceiling": 3000, "hp": 50, "sub_max": 0.6},
    "chime": {"ceiling": 3200, "hp": 80, "sub_max": 0.5},
    "tick": {"ceiling": 3500, "hp": 80, "sub_max": 0.5},
    "zap": {"ceiling": 3500, "hp": 60, "sub_max": 0.6},
    "texture": {"ceiling": 2600, "hp": 80, "sub_max": 0.6},
    "loop": {"ceiling": 2400, "hp": 80, "sub_max": 0.6},
    # pass 64, the hype family (engine sa3): scored by a brightness band [lo, hi] (Hz) instead of "lower wins", by
    # tonality (spectral flatness, weighted by `tonal`) and, for the jingles, by not dying before their length
    "pop": {"ceiling": 4000, "band": [700, 3200], "tonal": 1.5, "hp": 120, "sub_max": 0.3},
    "click": {"ceiling": 6000, "band": [1500, 5500], "tonal": 0.3, "hp": 150, "sub_max": 0.2},
    "casino": {"ceiling": 6500, "band": [1200, 5000], "tonal": 0.5, "hp": 70, "sub_max": 0.4},
    "jingle": {"ceiling": 6500, "band": [1400, 4800], "tonal": 1.5, "hp": 60, "sub_max": 0.4},
    "bling": {"ceiling": 7000, "band": [2000, 6000], "tonal": 2.0, "hp": 150, "sub_max": 0.2},
    "coin": {"ceiling": 7000, "band": [2200, 6500], "tonal": 0.5, "hp": 150, "sub_max": 0.2},
}
SUB_HZ = 120.0
# A candidate whose centroid sits under FLOOR_HZ is a rumble a phone speaker barely plays (the first Nuke blast and
# the Sun Scepter's strike came out at 170-180 Hz: silent in the game): it loses to any candidate above the floor.
FLOOR_HZ = 250.0

# id: (group, trigger, kind, seconds, pitch semitones, prompt). `seconds` is the length in the game (loops: the loop's
# length, crossfaded); the server is asked for ceil(seconds) + 1 (loops + 2). A None prompt = silenced (real/silence.wav).
# The prompts are positive sound-design descriptions in the register Garry asked for (low, deep, dull, dry, muffled);
# the stable engine appends STABLE_SUFFIX, the audiogen engine sends them bare (it has no negative prompting, and
# "no voice" would only steer it towards a voice).
P = {}


def _row(group, sid, trigger, kind, seconds, pitch, prompt):
    P[sid] = {"group": group, "trigger": trigger, "kind": kind, "seconds": seconds, "pitch": pitch, "prompt": prompt}


