_COMFY_AUDIO = None


def comfy_audio():
    """tools/comfy_audio.py, imported on first use (the stable and audiogen engines never need it)."""
    global _COMFY_AUDIO
    if _COMFY_AUDIO is None:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import comfy_audio as ca
        _COMFY_AUDIO = ca
    return _COMFY_AUDIO


def eng_dir(engine):
    return os.path.join(DL, engine)


def log(msg, engine=DEFAULT_ENGINE):
    os.makedirs(DL, exist_ok=True)
    line = "%s %s" % (datetime.datetime.now().strftime("%H:%M:%S"), msg)
    print(line, flush=True)
    with open(os.path.join(DL, LOGS[engine]), "a", encoding="utf-8") as f:
        f.write(line + "\n")


def seed_for(sid, k):
    return zlib.crc32(("%s:%d" % (sid, k)).encode("utf-8")) & 0x7FFFFFFF


def ask_duration(row, engine=DEFAULT_ENGINE):
    if engine == "sa3":
        # Stable Audio 3 shapes the sound to the length it is told (a 0.12 s tap asked as 2 s comes back as several)
        return round(max(row["seconds"] + 0.4, 0.6), 2)
    s = int(math.ceil(row["seconds"]))
    return s + (2 if row["kind"] == "loop" else 1)


def engine_prompt(engine, row):
    """The text sent to an engine: Stable Audio gets the suffix it honours, AudioGen the bare description."""
    base = row["prompt"]
    if engine != "stable" or base is None:
        return base
    suffix = STABLE_SUFFIX_STING if row["kind"] == "sting" else STABLE_SUFFIX
    return base if "no voice" in base.lower() else base + " " + suffix


def engine_negative(row):
    return STABLE_NEGATIVE_STING if row["kind"] == "sting" else STABLE_NEGATIVE


def cand_path(engine, sid, k, ext="wav"):
    return os.path.join(eng_dir(engine), "%s_c%d.%s" % (sid, k, ext))


def proc_path(engine, sid, k):
    return os.path.join(eng_dir(engine), "proc", "%s_c%d.wav" % (sid, k))


def cand_ks(engine, sid):
    """The candidate indices an id has on disk for an engine (`--cands N` above CANDS adds c3.. for a hard id: the
    analysis and the pick read whatever is there, so an extra candidate is never lost to a later default run)."""
    d = eng_dir(engine)
    if not os.path.isdir(d):
        return []
    ks = []
    for fn in os.listdir(d):
        m = re.match(r"^%s_c(\d+)\.json$" % re.escape(sid), fn)
        if m:
            ks.append(int(m.group(1)))
    return sorted(ks)


def scores_path(engine):
    return os.path.join(eng_dir(engine), "scores.json")


def picks_path():
    return os.path.join(DL, "picks.json")


def read_json(path, default):
    if not os.path.exists(path):
        return default
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(obj, f, indent=1, ensure_ascii=False)
        f.write("\n")


def sfx_ids():
    """Every non-music id of the table, in generation order."""
    rest = [k for k in PROMPTS if k not in ORDER_PREFIX]
    return [k for k in ORDER_PREFIX if k in PROMPTS] + rest


def gen_ids(engine=None):
    if engine == "sa3":
        return [k for k in sfx_ids() if k in HYPE]
    return [k for k in sfx_ids() if PROMPTS[k]["prompt"] is not None]


# ---------------------------------------------------------------- the Stable Audio server (gradio_client, Gradio 6)

def stable_client():
    """The gradio_client handle. Files are NOT downloaded by the client: the app's "verbose" file name carries the whole
    prompt (over Windows' 260-character path limit once a hash folder is put in front of it) and its short "output.wav"
    lands in the app's own folder, which Gradio refuses to serve (403). So the answer is the served URL, fetched here."""
    from gradio_client import Client
    try:
        return Client(STABLE_URL, download_files=False, verbose=False)
    except Exception as e:
        raise RuntimeError("no Stable Audio app at %s (%s: %s)" % (STABLE_URL, type(e).__name__, str(e)[:200]))


def _served_url(obj):
    """The URL Gradio serves a result file at, from the FileData dict (or a bare server path). The dict's own `url`
    is unquoted (the verbose file name has spaces and commas), so the path is quoted here."""
    path = url = None
    if isinstance(obj, dict):
        url = obj.get("url")
        path = obj.get("path") or obj.get("value")
    elif isinstance(obj, str):
        path = obj
    if path and not str(path).startswith("http"):
        return STABLE_URL.rstrip("/") + "/gradio_api/file=" + urllib.parse.quote(str(path), safe=":/\\")
    if url:
        head, sep, rest = url.partition("file=")
        return head + sep + urllib.parse.quote(urllib.parse.unquote(rest), safe=":/\\") if sep else url
    return None


def generate_clip_stable(client, prompt, seconds, seed, steps=STABLE_STEPS, cfg=STABLE_CFG, negative=STABLE_NEGATIVE):
    """One Stable Audio run through /generate. Returns (wav bytes, info dict). `seconds_total` and `steps` must be
    ints: the app sizes its tensors from them and raises on a float (2.0 fails, 2 works)."""
    t0 = time.time()
    r = client.predict(prompt=prompt, negative_prompt=negative, seconds_total=int(round(seconds)), cfg_scale=float(cfg),
                       steps=int(steps), preview_every=0, seed=int(seed), sampler_type="pingpong",
                       file_format="wav", file_naming="verbose", cut_to_seconds_total=True, api_name="/generate")
    first = r[0] if isinstance(r, (list, tuple)) else r
    url = _served_url(first)
    if not url:
        raise RuntimeError("no audio file in the answer: %s" % str(r)[:300])
    with urllib.request.urlopen(url, timeout=120) as resp:
        wav = resp.read()
    if len(wav) < 1000 or wav[:4] != b"RIFF":
        raise RuntimeError("the served file is not a wav (%d bytes) at %s" % (len(wav), url[:120]))
    return wav, {"elapsed": round(time.time() - t0, 1), "server_file": (first.get("path") if isinstance(first, dict) else str(first))}


# ---------------------------------------------------------------- the audiocraft_plus server (Gradio 3.50 queue ws)

def audiogen_config():
    with urllib.request.urlopen(AUDIOGEN_HOST + "/config", timeout=20) as r:
        return json.load(r)


def audiogen_build_data(cfg, prompt, duration, seed):
    comps = {c["id"]: c for c in cfg["components"]}
    dep = cfg["dependencies"][AUDIOGEN_FN]
    ids = dep["inputs"]
    data = [comps[cid].get("props", {}).get("value") for cid in ids]
    idx = {cid: i for i, cid in enumerate(ids)}
    I = AUDIOGEN_INPUT_IDS
    want = {I["mode"]: "audio", I["prompt"]: prompt, I["duration"]: int(duration), I["seed"]: int(seed),
            I["channels"]: "mono", I["rate"]: AUDIOGEN_SERVER_RATE, I["segments"]: 1, I["top_k"]: 250, I["top_p"]: 0,
            I["temperature"]: 1.0, I["cfg"]: 3.0}
    for cid, v in want.items():
        if cid not in idx:
            raise RuntimeError("the server's dependency %d has no input component %d: the app changed" % (AUDIOGEN_FN, cid))
        data[idx[cid]] = v
    return data


def audiogen_fetch_file(name):
    url = AUDIOGEN_HOST + "/file=" + urllib.parse.quote(name, safe=":/\\")
    with urllib.request.urlopen(url, timeout=120) as r:
        return r.read()


def generate_clip_audiogen(cfg, prompt, duration, seed, timeout=900):
    """One AudioGen run over the Gradio 3.50 queue websocket. Returns (wav bytes, server info dict)."""
    import websocket
    data = audiogen_build_data(cfg, prompt, duration, seed)
    sh = "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(11))
    ws = websocket.create_connection(AUDIOGEN_WS, timeout=timeout)
    t0 = time.time()
    try:
        while True:
            raw = ws.recv()
            if not raw:
                raise RuntimeError("the queue socket closed without an answer")
            m = json.loads(raw)
            msg = m.get("msg")
            if msg == "send_hash":
                ws.send(json.dumps({"fn_index": AUDIOGEN_FN, "session_hash": sh}))
            elif msg == "send_data":
                ws.send(json.dumps({"data": data, "fn_index": AUDIOGEN_FN, "session_hash": sh}))
            elif msg == "queue_full":
                raise RuntimeError("queue full")
            elif msg == "process_completed":
                if not m.get("success", False):
                    raise RuntimeError("the server failed: %s" % str(m.get("output", {}).get("error", m))[:300])
                out = m.get("output", {}).get("data", [])
                audio = out[1] if len(out) > 1 else None
                if not (isinstance(audio, dict) and audio.get("name")):
                    raise RuntimeError("no audio in the answer: %s" % str(out)[:300])
                info = {"server_file": audio["name"], "seed_used": out[4] if len(out) > 4 else None,
                        "elapsed": round(time.time() - t0, 1), "server_duration": m.get("output", {}).get("duration")}
                return audiogen_fetch_file(audio["name"]), info
            # estimation / process_starts / progress: keep waiting
    finally:
        try:
            ws.close()
        except Exception:
            pass


# ---------------------------------------------------------------- generation (both engines)

def cand_meta(engine, row, k, steps, cfg):
    m = {"engine": engine, "prompt": engine_prompt(engine, row), "seed": seed_for(row["_id"], k),
         "duration": ask_duration(row, engine)}
    if engine == "sa3":
        models = row.get("models") or ["medium", "app"]
        m.update({"model": models[k % len(models)], "steps": comfy_audio().STEPS, "cfg": comfy_audio().CFG})
    elif engine == "stable":
        m.update({"steps": int(steps), "cfg": float(cfg), "negative": engine_negative(row)})
    return m


def is_stale(engine, meta, want):
    if engine == "sa3":
        return (meta.get("prompt") != want["prompt"] or float(meta.get("duration", -1)) != float(want["duration"])
                or meta.get("model") != want["model"])
    if engine == "stable":
        return (meta.get("prompt") != want["prompt"] or int(meta.get("duration", -1)) != want["duration"]
                or int(meta.get("steps", -1)) != want["steps"] or float(meta.get("cfg", -1)) != want["cfg"])
    return meta.get("prompt") != want["prompt"] or int(meta.get("duration", -1)) != want["duration"]


def generate_all(engine=DEFAULT_ENGINE, only=None, force=False, dry=False, steps=STABLE_STEPS, cfg=STABLE_CFG,
                 cands=CANDS):
    ids = gen_ids(engine) if not only else [i for i in gen_ids(engine) if i in only]
    todo = []
    for sid in ids:
        row = dict(row_for(engine, sid), _id=sid)
        for k in range(cands):
            wav, meta = cand_path(engine, sid, k), cand_path(engine, sid, k, "json")
            have = os.path.exists(wav) and os.path.exists(meta)
            stale = False
            if have and not force:
                stale = is_stale(engine, read_json(meta, {}), cand_meta(engine, row, k, steps, cfg))
            if force or not have or stale:
                todo.append((sid, k, "stale" if stale else ("force" if (have and force) else "missing")))
    if dry:
        for sid in ids:
            r = row_for(engine, sid)
            print("%-18s %-8s %4.2fs ask %ss pitch %+d  %s" % (sid, r["kind"], r["seconds"], ask_duration(r, engine), r["pitch"],
                                                              engine_prompt(engine, r)))
        print("\n[%s] %d ids, %d clips to generate (%d candidates each)" % (engine, len(ids), len(todo), cands))
        for sid, k, why in todo[:40]:
            print("  %s_c%d (%s)" % (sid, k, why))
        if len(todo) > 40:
            print("  ... and %d more" % (len(todo) - 40))
        return 0
    if not todo:
        log("generate[%s]: nothing to do (%d ids complete)" % (engine, len(ids)), engine)
        return 0
    os.makedirs(eng_dir(engine), exist_ok=True)
    client = cfg_ag = None
    if engine == "sa3":
        log("generate[sa3]: %d clips for %d ids on %s (Stable Audio 3, %d steps, cfg %.1f, lcm/simple)"
            % (len(todo), len(ids), comfy_audio().comfy.SERVER, comfy_audio().STEPS, comfy_audio().CFG), engine)
    elif engine == "stable":
        client = stable_client()
        log("generate[stable]: %d clips for %d ids on %s (steps %d, cfg %.1f, 44.1 kHz stereo folded to mono)"
            % (len(todo), len(ids), STABLE_URL, steps, cfg), engine)
    else:
        cfg_ag = audiogen_config()
        log("generate[audiogen]: %d clips for %d ids on %s (fn %d, %s Hz mono)"
            % (len(todo), len(ids), AUDIOGEN_HOST, AUDIOGEN_FN, AUDIOGEN_SERVER_RATE), engine)
    failed = []
    t_all = time.time()
    for n, (sid, k, why) in enumerate(todo):
        row = dict(row_for(engine, sid), _id=sid)
        want = cand_meta(engine, row, k, steps, cfg)
        ok = False
        for attempt in range(1, 5):
            try:
                if engine == "sa3" and want["model"] == "app":
                    # Garry's Stable Audio app on this PC (the pass-60 engine) with the hype prompt: whole seconds only
                    if client is None:
                        client = stable_client()
                    wav, info = generate_clip_stable(client, want["prompt"], max(1, int(math.ceil(want["duration"]))),
                                                     want["seed"], STABLE_STEPS, STABLE_CFG, STABLE_NEGATIVE_STING)
                elif engine == "sa3":
                    wavs, secs = comfy_audio().generate(want["prompt"], want["duration"], want["seed"], want["model"], 1,
                                                        "88fits/sfx64/%s_c%d" % (sid, k))
                    wav, info = wavs[0], {"elapsed": round(secs, 1)}
                elif engine == "stable":
                    wav, info = generate_clip_stable(client, want["prompt"], want["duration"], want["seed"], want["steps"],
                                                     want["cfg"], want["negative"])
                else:
                    wav, info = generate_clip_audiogen(cfg_ag, want["prompt"], want["duration"], want["seed"])
                with open(cand_path(engine, sid, k), "wb") as f:
                    f.write(wav)
                write_json(cand_path(engine, sid, k, "json"), {"id": sid, "k": k, **want, "kind": row["kind"],
                                                               "seconds": row["seconds"], **info})
                log("[%d/%d] %s_c%d %s seed %d %ss in %.1fs" % (n + 1, len(todo), sid, k, why, want["seed"], want["duration"],
                                                               info["elapsed"]), engine)
                ok = True
                break
            except Exception as e:
                log("[%d/%d] %s_c%d attempt %d failed: %s %s" % (n + 1, len(todo), sid, k, attempt, type(e).__name__,
                                                                 str(e)[:200]), engine)
                time.sleep(15 * attempt)
                try:
                    if engine == "sa3":
                        client = None
                    elif engine == "stable":
                        client = stable_client()
                    else:
                        cfg_ag = audiogen_config()
                except Exception:
                    pass
        if not ok:
            failed.append("%s_c%d" % (sid, k))
    log("generate[%s]: done in %.1f min, %d failed%s" % (engine, (time.time() - t_all) / 60, len(failed),
                                                        (": " + ", ".join(failed)) if failed else ""), engine)
    return 1 if failed else 0


# ---------------------------------------------------------------- audio

def load_mono(path):
    import soundfile as sf
    y, sr = sf.read(path, dtype="float32", always_2d=True)
    return y.mean(axis=1), sr


def audiogen_true_rate(sr, n, duration):
    """audiocraft_plus labels its wav with the output rate it was asked for; a file whose sample count is the model's
    rate times the asked duration is really at AUDIOGEN_RATE whatever the header says."""
    if sr != AUDIOGEN_RATE and duration and abs(n - duration * AUDIOGEN_RATE) <= AUDIOGEN_RATE * 0.05:
        return AUDIOGEN_RATE
    return sr


def resample(y, sr, to):
    if sr == to:
        return y
    import librosa
    return librosa.resample(y, orig_sr=sr, target_sr=to, res_type="soxr_hq").astype(np.float32)


def highpass(y, sr, hz=40.0):
    from scipy.signal import butter, sosfiltfilt
    sos = butter(2, hz, "highpass", fs=sr, output="sos")
    return sosfiltfilt(sos, y).astype(np.float32)


def db(x):
    return 20.0 * math.log10(max(float(x), 1e-9))


def frame_rms(y, sr, win=0.005):
    n = max(int(win * sr), 1)
    m = len(y) // n
    if m == 0:
        return np.array([float(np.sqrt(np.mean(y ** 2)))]) if len(y) else np.zeros(1)
    fr = y[:m * n].reshape(m, n)
    return np.sqrt(np.mean(fr ** 2, axis=1))


def onset_index(y, sr, rel_db=-40.0, win=0.005):
    """First 5 ms frame within rel_db of the clip's peak frame; -1 when the clip is silent."""
    r = frame_rms(y, sr, win)
    top = float(r.max())
    if top <= 1e-6:
        return -1
    thr = top * (10 ** (rel_db / 20.0))
    i = int(np.argmax(r >= thr))
    return i * max(int(win * sr), 1)


def last_index_above(y, sr, rel_db=-45.0, win=0.005):
    r = frame_rms(y, sr, win)
    top = float(r.max())
    if top <= 1e-6:
        return 0
    thr = top * (10 ** (rel_db / 20.0))
    idx = np.nonzero(r >= thr)[0]
    return int((idx[-1] + 1) * max(int(win * sr), 1)) if len(idx) else 0


def fade(y, sr, fin=0.002, fout=0.03):
    y = y.copy()
    a = min(int(fin * sr), len(y) // 2)
    b = min(int(fout * sr), len(y) // 2)
    if a > 0:
        y[:a] *= np.linspace(0.0, 1.0, a, dtype=np.float32)
    if b > 0:
        y[-b:] *= np.linspace(1.0, 0.0, b, dtype=np.float32)
    return y


def pitch_shift(y, sr, semis):
    """Varispeed: `semis` semitones down (negative) by playing the clip slower, so it gets longer and lower with every
    transient intact (see the KINDS note for why not a phase vocoder)."""
    if not semis:
        return y
    import librosa
    f = 2.0 ** (-semis / 12.0)
    return librosa.resample(y, orig_sr=sr, target_sr=int(round(sr * f)), res_type="soxr_hq").astype(np.float32)


def content_rms(y, sr):
    """RMS over the 20 ms frames within 45 dB of the loudest one: the sound, not its silence."""
    fr = frame_rms(y, sr, 0.02)
    top = float(fr.max()) if len(fr) else 0.0
    if top <= 1e-6:
        return 0.0
    keep = fr >= top * 10 ** (-45 / 20.0)
    return float(np.sqrt(np.mean(fr[keep] ** 2)))


def limiter(y, sr, ceiling_db=CEILING_DB, attack=0.002, release=0.08):
    """A plain look-ahead peak limiter: the gain needed to keep every sample under the ceiling, taken over an attack
    window ahead (so the gain is down before the peak), released with a time constant; a hard clip as the safety."""
    from scipy.ndimage import minimum_filter1d
    c = 10 ** (ceiling_db / 20.0)
    need = np.minimum(1.0, c / np.maximum(np.abs(y), 1e-9)).astype(np.float64)
    n = max(int(attack * sr), 1)
    g = minimum_filter1d(need, size=2 * n + 1, mode="nearest")
    k = math.exp(-1.0 / (release * sr))
    out = np.empty_like(g)
    cur = 1.0
    for i in range(len(g)):
        gi = g[i]
        cur = gi if gi < cur else cur + (1.0 - k) * (gi - cur)
        out[i] = cur
    return np.clip(y * out, -c, c).astype(np.float32)


def level(y, sr):
    """Content RMS to TARGET_RMS_DB with at most MAX_LIMIT_DB of limiting at CEILING_DB (see the constants)."""
    rms = content_rms(y, sr)
    peak = float(np.max(np.abs(y))) if len(y) else 0.0
    if rms <= 1e-9 or peak <= 1e-9:
        return y
    c = 10 ** (CEILING_DB / 20.0)
    g = 10 ** (TARGET_RMS_DB / 20.0) / rms
    g = min(g, (c / peak) * 10 ** (MAX_LIMIT_DB / 20.0))
    return limiter((y * g).astype(np.float32), sr)


def cut_oneshot(y, sr, seconds):
    """Trim to the onset, cut at `seconds` (sooner when the sound has died away), fade in and out."""
    o = onset_index(y, sr)
    if o < 0:
        return y[:int(seconds * sr)]
    o = max(0, o - int(0.003 * sr))
    y = y[o:]
    n = int(seconds * sr)
    end = min(len(y), n)
    tail = last_index_above(y[:end], sr) + int(0.04 * sr)
    end = max(int(0.03 * sr), min(end, tail))
    y = y[:end]
    fout = min(0.06, max(0.02, seconds * 0.1))
    return fade(y, sr, 0.002, fout)


def steadiest_start(y, sr, need, step=0.05):
    """Start of the `need`-long window whose 100 ms RMS envelope varies least (the texture, not a swell)."""
    if len(y) <= need:
        return 0
    best, best_var = 0, None
    hop = max(int(step * sr), 1)
    for s in range(0, len(y) - need + 1, hop):
        env = frame_rms(y[s:s + need], sr, 0.1)
        env_db = 20.0 * np.log10(np.maximum(env, 1e-6))
        v = float(np.std(env_db)) + (3.0 if float(env.mean()) < 1e-3 else 0.0)
        if best_var is None or v < best_var:
            best, best_var = s, v
    return best


def make_loop(y, sr, seconds, xf=LOOP_XFADE):
    """A seamless `seconds` loop: a steady window of seconds + xf, its tail blended into its head."""
    n = int(seconds * sr)
    xn = int(xf * sr)
    need = n + xn
    if len(y) < need:
        reps = int(math.ceil(need / max(len(y), 1)))
        y = np.tile(y, reps)
    s = steadiest_start(y, sr, need)
    seg = y[s:s + need].copy()
    out = seg[:n].copy()
    if xn > 0:
        up = np.sin(np.linspace(0.0, math.pi / 2, xn, dtype=np.float32)) ** 2
        down = 1.0 - up
        out[:xn] = seg[:xn] * up + seg[n:n + xn] * down
    return out


def process(raw_path, row, duration, engine):
    """Raw server wav (stereo or mono, any rate) -> processed float clip at OUT_RATE, plus the raw measures of the score."""
    y, sr = load_mono(raw_path)
    if engine == "audiogen":
        sr = audiogen_true_rate(sr, len(y), duration)
    raw_peak = float(np.max(np.abs(y))) if len(y) else 0.0
    clip_frac = float(np.mean(np.abs(y) > 0.985)) if len(y) else 0.0
    onset_s = onset_index(y, sr) / float(sr) if len(y) else -1.0
    y = resample(y, sr, OUT_RATE)
    y = y - float(np.mean(y))
    y = highpass(y, OUT_RATE, float(KINDS[row["kind"]].get("hp", 40)))
    y = pitch_shift(y, OUT_RATE, row["pitch"])
    if row["kind"] == "loop":
        y = make_loop(y, OUT_RATE, row["seconds"])
    else:
        y = cut_oneshot(y, OUT_RATE, row["seconds"])
    y = level(y, OUT_RATE)
    return y, {"raw_rate": sr, "raw_seconds": round(len(y) / OUT_RATE, 3), "raw_peak": round(raw_peak, 3),
               "clip_frac": round(clip_frac, 4), "onset_s": round(onset_s, 3)}


def measure(y, sr):
    """Centroid (Hz, energy-weighted over the frames that carry the sound), RMS dBFS, content length, silence share,
    flatness, the share of energy under 500 Hz (the "low register" in one number) and under SUB_HZ (what a phone
    speaker drops)."""
    import librosa
    if len(y) < 64:
        return {"centroid": 0.0, "rms_db": -99.0, "content_s": 0.0, "silence_frac": 1.0, "flatness": 0.0, "low_share": 0.0,
                "sub_share": 0.0}
    n_fft = 1024 if len(y) >= 1024 else 256
    S = np.abs(librosa.stft(y, n_fft=n_fft, hop_length=n_fft // 4)) ** 2
    e = S.sum(axis=0)
    cent = librosa.feature.spectral_centroid(S=np.sqrt(S), sr=sr)[0]
    w = e / max(float(e.sum()), 1e-12)
    centroid = float(np.sum(cent * w))
    flat = float(np.sum(librosa.feature.spectral_flatness(S=np.sqrt(S))[0] * w))
    freqs = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
    total = max(float(S.sum()), 1e-12)
    low = float(S[freqs < 500.0].sum() / total)
    sub = float(S[freqs < SUB_HZ].sum() / total)
    rms = float(np.sqrt(np.mean(y ** 2)))
    fr = frame_rms(y, sr, 0.02)
    sil = float(np.mean(fr < 10 ** (-50 / 20.0)))
    return {"centroid": round(centroid, 1), "rms_db": round(db(rms), 2), "content_s": round(last_index_above(y, sr) / sr, 3),
            "silence_frac": round(sil, 3), "flatness": round(flat, 4), "low_share": round(low, 3), "sub_share": round(sub, 3)}


def hard_fail(m, row):
    """A candidate no ear would accept: empty, clipped at the source, or a loop that is mostly silence."""
    if m["content_s"] < 0.03 or m["rms_db"] < -40:
        return "empty"
    if m.get("clip_frac", 0.0) > 0.01:
        return "clipped"
    if row["kind"] == "loop" and m["silence_frac"] > 0.2:
        return "gappy loop"
    return ""


def score_candidate(m, raw, row):
    """Lower is better. The centroid against the kind's ceiling carries it; clipping, emptiness, a sound that is mostly
    sub-bass or whose centroid is under FLOOR_HZ (inaudible on a phone), a sound that died long before its length (not
    for hits) and a loop that swells add penalties."""
    kind = KINDS[row["kind"]]
    if "band" in kind:
        return score_hype(m, raw, row, kind)
    ceiling = kind["ceiling"]
    s = m["centroid"] / ceiling
    if m["centroid"] > ceiling:
        s += 2.0
    if m["centroid"] < FLOOR_HZ:
        s += 1.0
    sub = m.get("sub_share", 0.0)
    if sub > kind.get("sub_max", 0.6):
        s += 1.0 + (2.0 if sub > 0.85 else 0.0)
    if raw["clip_frac"] > 0.01:
        s += 1.0 + raw["clip_frac"] * 10
    if m["content_s"] < 0.03 or m["rms_db"] < -40:
        s += 5.0
    if row["kind"] not in ("impact", "tick", "chime", "shot") and m["content_s"] < 0.5 * row["seconds"]:
        s += 1.0
    if row["kind"] == "loop" and m["silence_frac"] > 0.2:
        s += 1.5
    if raw["onset_s"] > 1.5:
        s += 0.5
    return round(s, 4)


def score_hype(m, raw, row, kind):
    """Lower is better (pass 64, the hype family): the centroid's distance outside the kind's brightness band (inside
    it, its distance from the band's middle, lightly), noisiness (spectral flatness x `tonal`: a chime or a jingle
    should ring, not hiss), a jingle that died before 60 % of its length, clipping, emptiness, sub-bass."""
    lo, hi = kind["band"]
    c = m["centroid"]
    mid = math.sqrt(lo * hi)
    s = 0.3 * abs(math.log(max(c, 1.0) / mid)) / math.log(hi / mid)
    if c < lo:
        s += 1.0 + math.log(lo / max(c, 1.0))
    elif c > hi:
        s += 1.0 + math.log(c / hi)
    s += kind.get("tonal", 1.0) * m.get("flatness", 0.0) * 4.0
    if m.get("sub_share", 0.0) > kind.get("sub_max", 0.4):
        s += 1.0
    if raw.get("clip_frac", 0.0) > 0.01:
        s += 1.0 + raw["clip_frac"] * 10
    if m["content_s"] < 0.03 or m["rms_db"] < -40:
        s += 5.0
    if row["kind"] == "jingle" and m["content_s"] < 0.6 * row["seconds"]:
        s += 1.0
    if row["kind"] in ("pop", "click") and m["content_s"] > 1.5 * row["seconds"] + 0.05:
        s += 0.5
    if raw.get("onset_s", 0.0) > 0.4:
        s += 0.5
    return round(s, 4)


def write_wav(path, y, sr=OUT_RATE):
    import soundfile as sf
    os.makedirs(os.path.dirname(path), exist_ok=True)
    sf.write(path, np.clip(y, -1.0, 1.0), sr, subtype="PCM_16")


def placeholder_measure(sid):
    p = os.path.join(SOUNDS, "placeholder", sid + ".wav")
    if not os.path.exists(p):
        return None
    y, sr = load_mono(p)
    return measure(resample(y, sr, OUT_RATE), OUT_RATE)


def analyse_all(engine=DEFAULT_ENGINE, only=None, fresh=False):
    """Process every candidate of an engine on disk into its proc/, measure it and write its scores.json. A candidate
    whose processed file is newer than its raw file is kept unless `fresh`. Returns the scores."""
    scores = read_json(scores_path(engine), {})
    ids = gen_ids(engine) if not only else [i for i in gen_ids(engine) if i in only]
    for sid in ids:
        row = row_for(engine, sid)
        old_cands = {c["k"]: c for c in scores.get(sid, {}).get("cands", [])}
        cands = []
        for k in cand_ks(engine, sid):
            raw = cand_path(engine, sid, k)
            meta = read_json(cand_path(engine, sid, k, "json"), {})
            if not os.path.exists(raw) or not meta:
                continue
            pp = proc_path(engine, sid, k)
            if (not fresh and k in old_cands and os.path.exists(pp) and os.path.getmtime(pp) >= os.path.getmtime(raw)
                    and old_cands[k].get("prompt") == meta.get("prompt") and old_cands[k].get("pitch") == row["pitch"]
                    and old_cands[k].get("target_s") == row["seconds"]):
                cands.append(old_cands[k])
                continue
            try:
                y, rawm = process(raw, row, float(meta.get("duration", ask_duration(row, engine))), engine)
            except Exception as e:
                log("analyse[%s]: %s_c%d failed: %s %s" % (engine, sid, k, type(e).__name__, e), engine)
                continue
            write_wav(pp, y)
            m = measure(y, OUT_RATE)
            m.update(rawm)
            m["k"] = k
            m["seed"] = meta.get("seed")
            m["prompt"] = meta.get("prompt")
            m["pitch"] = row["pitch"]
            m["target_s"] = row["seconds"]
            m["seconds"] = round(len(y) / OUT_RATE, 3)
            m["score"] = score_candidate(m, rawm, row)
            m["fail"] = hard_fail(m, row)
            cands.append(m)
        if cands:
            old = placeholder_measure(sid)
            scores[sid] = {"cands": cands, "old": old, "kind": row["kind"], "ceiling": KINDS[row["kind"]]["ceiling"]}
    write_json(scores_path(engine), scores)
    return scores


def all_scores():
    return {e: read_json(scores_path(e), {}) for e in ENGINES}


def best_of(cands):
    return min(cands, key=lambda c: (c["score"], c["centroid"])) if cands else None


def pick_auto(picks, only=None, force=False, partial=False, prefer=DEFAULT_ENGINE):
    """The preferred engine's best candidate per id; the other engine's only when every preferred candidate fails hard
    (empty, clipped, a gappy loop) and the other has one that does not. Returns (changed, fallbacks)."""
    scores = all_scores()
    others = [e for e in ENGINES if e != prefer]
    changed, fallbacks = 0, []
    for sid in gen_ids():
        if only and sid not in only:
            continue
        if sid in picks and picks[sid].get("manual") and not force:
            continue
        pref = "sa3" if sid in HYPE and scores["sa3"].get(sid, {}).get("cands") else prefer
        row = row_for(pref, sid)
        mine = scores[pref].get(sid, {}).get("cands", [])
        if not mine or (len(mine) < CANDS and not partial):
            continue
        engine, best = pref, best_of(mine)
        if all(hard_fail(c, row) for c in mine):
            for e in [x for x in others if x != pref]:
                ok = [c for c in scores[e].get(sid, {}).get("cands", []) if not hard_fail(c, row)]
                if ok:
                    engine, best = e, best_of(ok)
                    fallbacks.append((sid, e, "every %s candidate: %s" % (prefer, ", ".join(hard_fail(c, row) for c in mine))))
                    break
        picks[sid] = {"engine": engine, "k": best["k"], "score": best["score"], "centroid": best["centroid"], "manual": False}
        changed += 1
    return changed, fallbacks


def write_silence():
    n = int(SILENCE_SECONDS * OUT_RATE)
    write_wav(os.path.join(REAL, SILENCE), np.zeros(n, dtype=np.float32))


def bind(picks, only=None):
    """Copy every picked candidate into real/<id>.wav and point the soundmap rows at real/."""
    os.makedirs(REAL, exist_ok=True)
    write_silence()
    files = {}
    for sid, row in PROMPTS.items():
        if only and sid not in only:
            continue
        if sid in SYNTH:
            continue
        if row["prompt"] is None:
            files[sid] = "real/" + SILENCE
            continue
        p = picks.get(sid)
        if p is None:
            continue
        src = proc_path(p.get("engine", "audiogen"), sid, p["k"])
        if not os.path.exists(src):
            continue
        y, sr = load_mono(src)
        write_wav(os.path.join(REAL, sid + ".wav"), y, sr)
        files[sid] = "real/%s.wav" % sid
    changed = edit_soundmap(files)
    log("bind: %d wavs in real/, %d soundmap rows changed" % (len(files), changed))
    return files


def edit_soundmap(files, volumes=None):
    """Line-preserving edit of soundmap.json: sets the `file` of the ids in `files` (adding the key last, as the voice
    rows had it) and the `volume_db` of the ids in `volumes`; every other byte stays. Music rows are never touched."""
    volumes = volumes or {}
    with open(SOUNDMAP, encoding="utf-8", newline="") as f:
        text = f.read()
    nl = "\r\n" if "\r\n" in text else "\n"
    lines = text.split(nl)
    changed = 0
    i = 0
    while i < len(lines):
        m = re.match(r'^(\s{4})"([a-z0-9_]+)": \{\s*$', lines[i])
        if not m:
            i += 1
            continue
        sid = m.group(2)
        j = i + 1
        while j < len(lines) and not re.match(r'^\s{4}\}', lines[j]):
            j += 1
        if sid.startswith(MUSIC_PREFIX) or (sid not in files and sid not in volumes):
            i = j + 1
            continue
        body = lines[i + 1:j]
        if sid in volumes:
            for b, ln in enumerate(body):
                mm = re.match(r'^(\s+"volume_db": )(-?[0-9.]+)(,?)\s*$', ln)
                if mm and float(mm.group(2)) != float(volumes[sid]):
                    body[b] = "%s%s%s" % (mm.group(1), _num(volumes[sid]), mm.group(3))
                    changed += 1
        if sid in files:
            found = False
            for b, ln in enumerate(body):
                mm = re.match(r'^(\s+"file": )"([^"]*)"(,?)\s*$', ln)
                if mm:
                    found = True
                    if mm.group(2) != files[sid]:
                        body[b] = '%s"%s"%s' % (mm.group(1), files[sid], mm.group(3))
                        changed += 1
            if not found and body:
                indent = re.match(r'^(\s*)', body[-1]).group(1)
                if not body[-1].rstrip().endswith(","):
                    body[-1] = body[-1].rstrip() + ","
                body.append('%s"file": "%s"' % (indent, files[sid]))
                changed += 1
        lines[i + 1:j] = body
        i = i + 1 + len(body) + 1
    if changed:
        with open(SOUNDMAP, "w", encoding="utf-8", newline="") as f:
            f.write(nl.join(lines))
    return changed


def _num(v):
    return str(int(v)) if float(v) == int(v) else ("%.1f" % v)


def soundmap_rows():
    with open(SOUNDMAP, encoding="utf-8") as f:
        return json.load(f)["sounds"]


def write_sounds_json():
    """docs/design/src/sounds.json, the bible's section 16 table: every id with its trigger and its final prompt (the
    text the shipping engine was given), grouped as the page groups them; the six music rows are kept as they are.
    json.dump(indent=1) reproduces the file's format."""
    path = os.path.join(ROOT, "docs", "design", "src", "sounds.json")
    old = read_json(path, [])
    music = [r for r in old if r["id"].startswith(MUSIC_PREFIX)]
    picks = read_json(picks_path(), {})
    rows = []
    for g in GROUP_ORDER:
        if g == "Music":
            rows.extend(music)
            continue
        for sid, r in PROMPTS.items():
            if r["group"] != g:
                continue
            if r["prompt"] is None:
                prompt = "Silent (a 50 ms file): the voice bark is gone, nothing replaces it"
            else:
                e = picks.get(sid, {}).get("engine", DEFAULT_ENGINE)
                prompt = engine_prompt(e, row_for(e, sid))
            rows.append({"group": g, "id": sid, "trigger": r["trigger"], "prompt": prompt})
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(rows, f, indent=1, ensure_ascii=False)
    print("wrote %s: %d rows" % (path, len(rows)))


def report(picks):
    """A table of old vs new centroid and level per id, the share that went lower, the engines' share."""
    scores = all_scores()
    lower = total = 0
    by_engine = {e: 0 for e in ENGINES}
    rows = []
    for sid in gen_ids():
        p = picks.get(sid)
        if not p:
            continue
        e = p.get("engine", "audiogen")
        s = scores[e].get(sid)
        if not s:
            continue
        c = next((c for c in s["cands"] if c["k"] == p["k"]), None)
        if c is None:
            continue
        old = s.get("old") or {}
        total += 1
        by_engine[e] += 1
        oc = old.get("centroid")
        if oc is not None and c["centroid"] < oc:
            lower += 1
        drms = (c["rms_db"] - old["rms_db"]) if old.get("rms_db") is not None else None
        rows.append((sid, oc, c["centroid"], c["rms_db"], drms, c["seconds"], e, p["k"], p["score"],
                     "ear" if p.get("manual") else "auto"))
    print("%-18s %8s %8s %7s %7s %6s %-8s %2s %6s %s" % ("id", "old Hz", "new Hz", "rms dB", "d rms", "s", "engine", "k", "score", "pick"))
    for r in rows:
        print("%-18s %8s %8.0f %7.1f %7s %6.2f %-8s %2d %6.2f %s" % (
            r[0], ("%.0f" % r[1]) if r[1] is not None else "-", r[2], r[3], ("%+.1f" % r[4]) if r[4] is not None else "-",
            r[5], r[6], r[7], r[8], r[9]))
    if total:
        print("\ncentroid lower than the placeholder: %d of %d (%.0f%%); engines: %s" % (
            lower, total, 100.0 * lower / total, ", ".join("%s %d" % (e, n) for e, n in by_engine.items())))


def parse_pick(text):
    """'id=k' (the default engine) or 'id=engine:k'."""
    sid, val = text.split("=")
    sid = sid.strip()
    val = val.strip()
    engine = DEFAULT_ENGINE
    if ":" in val:
        engine, val = val.split(":")
        engine = engine.strip()
    if engine not in ENGINES:
        raise SystemExit("unknown engine in --pick %s (%s)" % (text, "|".join(ENGINES)))
    return sid, engine, int(val)


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--engine", default=DEFAULT_ENGINE, choices=ENGINES, help="which model generates (default stable)")
    ap.add_argument("--only", default="", help="comma-separated ids")
    ap.add_argument("--force", action="store_true", help="generate again / re-pick over manual picks")
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--gen-only", action="store_true", help="generate, do not pick or write")
    ap.add_argument("--steps", type=int, default=STABLE_STEPS, help="stable: sampler steps (default %d)" % STABLE_STEPS)
    ap.add_argument("--cfg", type=float, default=STABLE_CFG, help="stable: guidance scale (default %.1f)" % STABLE_CFG)
    ap.add_argument("--auto", action="store_true", help="pick by score (manual picks kept unless --force)")
    ap.add_argument("--partial", action="store_true", help="auto-pick ids with fewer than CANDS candidates too")
    ap.add_argument("--cands", type=int, default=CANDS,
                    help="candidates to generate per id (default %d; more for a hard id, with --only)" % CANDS)
    ap.add_argument("--analyse", action="store_true", help="process and score the engine's candidates again (fresh)")
    ap.add_argument("--rescore", action="store_true",
                    help="score every stored candidate again from its measures (a changed scoring rule), both engines")
    ap.add_argument("--pick", action="append", default=[], help="id=k or id=engine:k, a pick by ear")
    ap.add_argument("--bind", action="store_true", help="write real/ and the soundmap from the picks, no generation")
    ap.add_argument("--volume", action="append", default=[], help="id=dB, a volume_db re-level in the soundmap")
    ap.add_argument("--report", action="store_true", help="print the old vs new table")
    ap.add_argument("--docs", action="store_true", help="write docs/design/src/sounds.json from the table")
    a = ap.parse_args(argv)
    only = set(x.strip() for x in a.only.split(",") if x.strip()) or None
    if only:
        unknown = [x for x in only if x not in PROMPTS]
        if unknown:
            print("unknown ids:", ", ".join(unknown))
            return 2
    picks = read_json(picks_path(), {})
    rc = 0
    if a.volume:
        vols = {}
        for v in a.volume:
            sid, val = v.split("=")
            vols[sid.strip()] = float(val)
        n = edit_soundmap({}, vols)
        print("volume_db rows changed:", n)
    if a.pick:
        wanted = [parse_pick(p) for p in a.pick]
        for e in set(w[1] for w in wanted):
            analyse_all(e, only=set(w[0] for w in wanted if w[1] == e))
        scores = all_scores()
        for sid, engine, k in wanted:
            c = next((c for c in scores[engine].get(sid, {}).get("cands", []) if c["k"] == k), None)
            if c is None:
                print("no %s candidate %d for %s" % (engine, k, sid))
                rc = 2
                continue
            picks[sid] = {"engine": engine, "k": k, "score": c["score"], "centroid": c["centroid"], "manual": True}
            print("picked %s = %s c%d (centroid %.0f Hz)" % (sid, engine, k, c["centroid"]))
        write_json(picks_path(), picks)
        bind(picks, only=set(w[0] for w in wanted))
        return rc
    if a.bind:
        bind(picks, only=only)
        return 0
    if a.report:
        report(picks)
        return 0
    if a.docs:
        write_sounds_json()
        return 0
    if a.analyse:
        analyse_all(a.engine, only=only, fresh=True)
        return 0
    if a.rescore:
        for e in ENGINES:
            scores = read_json(scores_path(e), {})
            n = 0
            for sid, s in scores.items():
                if sid not in PROMPTS:
                    continue
                row = row_for(e, sid)
                for c in s["cands"]:
                    c["score"] = score_candidate(c, c, row)
                    c["fail"] = hard_fail(c, row)
                    n += 1
            write_json(scores_path(e), scores)
            print("rescored %d %s candidates" % (n, e))
        return 0
    if not a.auto:
        rc = generate_all(a.engine, only=only, force=a.force, dry=a.dry_run, steps=a.steps, cfg=a.cfg, cands=a.cands)
        if a.dry_run or a.gen_only:
            return rc
    analyse_all(a.engine, only=only)
    n, fallbacks = pick_auto(picks, only=only, force=a.force and a.auto, partial=a.partial, prefer=a.engine)
    write_json(picks_path(), picks)
    log("auto[%s]: %d ids picked, %d from the other engine%s" % (a.engine, n, len(fallbacks),
        ("; " + "; ".join("%s -> %s (%s)" % f for f in fallbacks)) if fallbacks else ""), a.engine)
    bind(picks, only=only)
    report(picks)
    return rc


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    sys.exit(main())
